const MONTHS = ["December 2024", "November 2024", /* ... */ "January 2024"];

// one Balance + Revenue column per month, grouped under the month name
MONTHS.forEach((month, i) => {
  cols.push({ key: `m${i}-bal`, label: "Balance", group: month,
    sortValue: (n) => n.measures.months[i].balance,
    renderer: money((n) => n.measures.months[i].balance) });
  cols.push({ key: `m${i}-rev`, label: "Revenue", group: month,
    sortValue: (n) => n.measures.months[i].revenue,
    renderer: money((n) => n.measures.months[i].revenue) });
});
